      danger: styles.colors.danger,
    },
    size: {
      default: styles.size.default,
      sm: styles.size.sm,
      lg: styles.size.lg,
      icon: styles.size.icon,
    },
  },
  defaultVariants: {
    variant: 'solid',
    color: 'primary',
    size: 'default',
  },
})

type ButtonProps = VariantProps<typeof buttonVariants> & {
  className?: string
  children: React.ReactNode
  /** Stretch button to fill its container width. */
  block?: boolean
  /** Show a spinner and disable interaction. */
  loading?: boolean
  /** Horizontal alignment of button content. */
  alignContent?: 'center' | 'start'
  disabled?: boolean
  /** Icon component rendered before the label. */
  leadingVisual?: React.ElementType
  /** Icon component rendered after the label. */
  trailingVisual?: React.ElementType
  /** Icon component rendered as a trailing action (far end). */
  trailingAction?: React.ElementType
  /** Allow the button label to wrap onto multiple lines. Defaults to true. */
  labelWrap?: boolean
  /** Optional numeric badge rendered after the label. */
  count?: number
} & (
    | Omit<Headless.ButtonProps, 'as' | 'className' | 'disabled'>
    | Omit<React.ComponentPropsWithoutRef<typeof Link>, 'className' | 'variant'>
  )

const Button = forwardRef(function Button(
  {
    className,
    variant,
    color,
    size,
    children,
    block,
    loading,
    alignContent = 'center',
    disabled,
    leadingVisual: LeadingVisual,
    trailingVisual: TrailingVisual,
    trailingAction: TrailingAction,
    labelWrap,
    count,
    ...props
  }: ButtonProps,
  ref: React.ForwardedRef<HTMLElement>
) {
  const effectiveDisabled = disabled || loading

  const classes = cn(
    buttonVariants({ variant, color, size }),
    block && 'w-full',
    alignContent === 'start' && 'justify-start',
    className
  )

  const content = (
    <TouchTarget>
      {loading && <ButtonSpinner />}
      {LeadingVisual && <LeadingVisual data-slot="icon" />}
      {labelWrap === false ? (
        <span className="whitespace-nowrap">{children}</span>
      ) : (
        children
      )}
      {count !== undefined && (
        <span className="rounded-full px-1.5 py-0.5 text-xs font-medium tabular-nums opacity-75">
          {count}
        </span>
      )}
      {TrailingVisual && <TrailingVisual data-slot="icon" />}
      {TrailingAction && <TrailingAction data-slot="icon" />}
    </TouchTarget>
  )

  return 'href' in props ? (
    <Link
      data-variant={variant}
      {...(props as Omit<
        React.ComponentPropsWithoutRef<typeof Link>,
        'className' | 'variant'
      >)}
      {...(effectiveDisabled
        ? {
            'aria-disabled': true,
            'data-disabled': '',
            tabIndex: -1,
            onClick: (e: React.MouseEvent<HTMLAnchorElement>) =>
              e.preventDefault(),
          }
        : {})}
      className={clsx(
        classes,
        effectiveDisabled ? 'cursor-not-allowed' : 'cursor-pointer'
      )}
      ref={ref as React.ForwardedRef<HTMLAnchorElement>}
    >
      {content}
    </Link>
  ) : (
    <Headless.Button
      data-variant={variant}
      {...(props as Omit<
        Headless.ButtonProps,
        'as' | 'className' | 'disabled'
      >)}
      disabled={effectiveDisabled}
      className={clsx(
        classes,
        effectiveDisabled ? 'cursor-not-allowed' : 'cursor-pointer'
      )}
      ref={ref}
    >
      {content}
    </Headless.Button>
  )
})

/** Inline spinner — avoids importing the full Icons module into the button bundle. */
function ButtonSpinner() {
  return (
    <svg
      data-slot="icon"
      className="animate-spin motion-reduce:animate-none"
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
      aria-hidden="true"
    >
      <circle
        className="opacity-25"
        cx="12"
        cy="12"
        r="10"
        stroke="currentColor"
        strokeWidth="4"
      />
      <path
        className="opacity-75"
        fill="currentColor"
        d="M4 12a8 8 0 018-8V0C5.373 0 22 5.373 22 12h-4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
      />
    </svg>
  )
}

/**
 * Expand the hit area to at least 44×44px on touch devices
 */
function TouchTarget({ children }: { children: React.ReactNode }) {
  return (
    <>
      <span
        className="absolute top-1/2 left-1/2 size-[max(100%,2.75rem)] -translate-x-1/2 -translate-y-1/2 rounded-sm bg-transparent [@media(pointer:fine)]:hidden"
        aria-hidden="true"
      />
      {children}
    </>
  )
}

export { Button, buttonVariants, TouchTarget }

'use client'

import * as Headless from '@headlessui/react'
import React, { createContext, forwardRef, useContext } from 'react'

type LinkComponent = React.ElementType

type LinkProps = Omit<React.ComponentPropsWithoutRef<'a'>, 'href'> & {
  as?: LinkComponent
  href: React.ComponentPropsWithoutRef<'a'>['href'] | object
}

const LinkComponentContext = createContext<LinkComponent | null>(null)

function LinkProvider({
  children,
  component,
}: {
  children: React.ReactNode
  component: LinkComponent
}) {
  return (
    <LinkComponentContext.Provider value={component}>
      {children}
    </LinkComponentContext.Provider>
  )
}

const Link = forwardRef(function Link(
  { as, ...props }: LinkProps,
  ref: React.ForwardedRef<HTMLAnchorElement>
) {
  const ContextLink = useContext(LinkComponentContext)
  const Component = as ?? ContextLink ?? 'a'

  return (
    <Headless.DataInteractive>
      <Component {...props} ref={ref} />
    </Headless.DataInteractive>
  )
})

export { Link, LinkProvider }
export type { LinkComponent, LinkProps }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) {
    return text
  }
  return text.slice(0, maxLength) + '...'
}

export function kebabCase(str: string) {
  return str
    .replace(/([a-z])([A-Z])/g, '$1-$2')
    .replace(/[\s_]+/g, '-')
    .toLowerCase()
}

export function camelCase(str: string) {
  return str
    .toLowerCase()
    .replace(/[^a-zA-Z0-9]+(.)/g, (_, chr) => chr.toUpperCase())
}

export function humaniseVariant(key: string): string {
  return key
    .replace(/([a-z])([A-Z0-9])/g, '$1 $2')
    .replace(/([0-9])([A-Za-z])/g, '$1 $2')
    .replace(/_/g, ' ')
    .replace(/\bFull\s?Width\b/gi, 'full width')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^./, (s) => s.toUpperCase())
}
